const data = $('Prepare Success Response').first().json;

// Limpiar el + del teléfono para la API de WhatsApp
const phone = (data.phone || '').replace(/^\+/, '').replace(/\s/g, '');

// Formatear fecha
const dateObj = new Date(data.date + 'T00:00:00');
const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
const formattedDate = dateObj.toLocaleDateString('es-CL', options);

const meetLink = data.meet_link || 'Te llegará por correo';

const messageBody = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: phone,
  type: 'interactive',
  interactive: {
    type: 'button',
    body: {
      text: `📅 *REUNIÓN DE SEGUIMIENTO*\n━━━━━━━━━━━━━━━━━━━━\n\nHola ${data.client_name}, hemos programado una reunión para continuar afinando los detalles de tu proyecto de automatización.\n\n📆 *Fecha:* ${formattedDate}\n🕐 *Hora:* ${data.time} hrs (Chile)\n📌 *Tema:* ${data.subject}\n💻 *Modalidad:* Videollamada Google Meet\n\n🔗 *Link de acceso:*\n${meetLink}\n\n━━━━━━━━━━━━━━━━━━━━\n¿Confirmas tu asistencia a esta reunión?`
    },
    action: {
      buttons: [
        {
          type: 'reply',
          reply: {
            id: `btn_followup_confirm_${data.meeting_id}`,
            title: '✅ Sí, confirmo'
          }
        },
        {
          type: 'reply',
          reply: {
            id: `btn_followup_reschedule_${data.meeting_id}`,
            title: '📅 Reagendar'
          }
        }
      ]
    }
  }
};

return {
  json: {
    ...data,
    phone_clean: phone,
    whatsappBody: JSON.stringify(messageBody)
  }
};
